    {"name": "Einstein's Field Equations", "equation": "G_{\\mu\\nu} + \\Lambda g_{\\mu\\nu} = \\frac{8\\pi G}{c^4} T_{\\mu\\nu}", "context": "General relativity"},
    {"name": "Schwarzschild Metric", "equation": "ds^2 = -\\left(1 - \\frac{2GM}{rc^2}\\right)c^2 dt^2 + \\frac{dr^2}{1 - \\frac{2GM}{rc^2}} + r^2 d\\Omega^2", "context": "General relativity"},
    {"name": "Schwarzschild Radius", "equation": "r_s = \\frac{2GM}{c^2}", "context": "General relativity"},
    {"name": "Friedmann Equation", "equation": "\\left(\\frac{\\dot{a}}{a}\\right)^2 = \\frac{8\\pi G \\rho + \\Lambda c^2}{3}", "context": "Cosmology"},
    {"name": "Hubble's Law", "equation": "v = H_0 d", "context": "Cosmology"},
    {"name": "Cosmological Redshift", "equation": "1 + z = \\frac{a_{\\text{now}}}{a_{\\text{then}}}", "context": "Cosmology"},
    {"name": "Gravitational Time Dilation", "equation": "\\Delta t = \\frac{\\Delta t_0}{\\sqrt{1 - \\frac{2GM}{rc^2}}}", "context": "General relativity"},
    {"name": "Geodesic Equation", "equation": "\\frac{d^2 x^\\mu}{d\\tau^2} + \\Gamma^\\mu_{\\nu\\rho} \\frac{dx^\\nu}{d\\tau} \\frac{dx^\\rho}{d\\tau} = 0", "context": "General relativity"},
    {"name": "Gravitational Wave Strain", "equation": "h = \\frac{2G}{c^4} \\frac{\\ddot{Q}_{ij}}{r}", "context": "General relativity"},
    {"name": "Luminosity Distance", "equation": "d_L = \\sqrt{\\frac{L}{4\\pi F}}", "context": "Cosmology"},
    {"name": "FLRW Metric", "equation": "ds^2 = -c^2 dt^2 + a(t)^2\\left[\\frac{dr^2}{1-kr^2} + r^2 d\\Omega^2 \\right]", "context": "Cosmology"},
    {"name": "Critical Density", "equation": "\\rho_c = \\frac{3H_0^2}{8\\pi G}", "context": "Cosmology"},
    {"name": "Cosmological Constant (Dark Energy)", "equation": "\\Omega_\\Lambda = \\frac{\\Lambda c^2}{3H_0^2}", "context": "Cosmology"},
    {"name": "Relativistic Doppler Effect", "equation": "f_{\\text{obs}} = f_{\\text{src}} \\sqrt{\\frac{1+\\beta}{1-\\beta}}", "context": "Special relativity"},
    {"name": "Energy-Momentum Relation", "equation": "E^2 = (pc)^2 + (mc^2)^2", "context": "Special relativity"},
    # === MATHEMATICS: ALGEBRA (196-230) ===
    {"name": "Quadratic Formula", "equation": "x = \\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a}", "context": "Algebra"},
    {"name": "Difference of Squares", "equation": "a^2 - b^2 = (a+b)(a-b)", "context": "Algebra"},
    {"name": "Sum of Cubes", "equation": "a^3 + b^3 = (a+b)(a^2 - ab + b^2)", "context": "Algebra"},
    {"name": "Binomial Theorem", "equation": "(x+y)^n = \\sum_{k=0}^{n} \\binom{n}{k} x^{n-k} y^k", "context": "Algebra"},
    {"name": "Pascal's Triangle", "equation": "\\binom{n}{k} = \\binom{n-1}{k-1} + \\binom{n-1}{k}", "context": "Combinatorics"},
    {"name": "Logarithm Definition", "equation": "\\log_b(a) = c \\iff b^c = a", "context": "Algebra"},
    {"name": "Change of Base", "equation": "\\log_b(a) = \\frac{\\log_c(a)}{\\log_c(b)}", "context": "Algebra"},
    {"name": "Euler's Formula", "equation": "e^{i\\theta} = \\cos\\theta + i\\sin\\theta", "context": "Complex analysis"},
    {"name": "De Moivre's Theorem", "equation": "(\\cos\\theta + i\\sin\\theta)^n = \\cos(n\\theta) + i\\sin(n\\theta)", "context": "Complex analysis"},
    {"name": "Fundamental Theorem of Algebra", "equation": "P(z) = a\\prod_{k=1}^{n} (z - r_k), \\quad \\deg(P) = n \\text{ has } n \\text{ complex roots}", "context": "Algebra"},
    {"name": "Matrix Multiplication", "equation": "(AB)_{ij} = \\sum_k A_{ik} B_{kj}", "context": "Linear algebra"},
    {"name": "Determinant (2x2)", "equation": "\\det\\begin{pmatrix} a & b \\\\ c & d \\end{pmatrix} = ad - bc", "context": "Linear algebra"},
    {"name": "Cramer's Rule", "equation": "x_i = \\frac{\\det(A_i)}{\\det(A)}", "context": "Linear algebra"},
    {"name": "Inverse of 2x2 Matrix", "equation": "A^{-1} = \\frac{1}{\\det(A)} \\begin{pmatrix} d & -b \\\\ -c & a \\end{pmatrix}", "context": "Linear algebra"},
    {"name": "Cayley-Hamilton Theorem", "equation": "p(A) = 0 \\quad \\text{(characteristic polynomial of }A\\text{)}", "context": "Linear algebra"},
    {"name": "Gram-Schmidt Process", "equation": "\\mathbf{u}_k = \\mathbf{v}_k - \\sum_{j<k} \\operatorname{proj}_{\\mathbf{u}_j}(\\mathbf{v}_k)", "context": "Linear algebra"},
    {"name": "Eigenvalue Equation", "equation": "A\\mathbf{v} = \\lambda \\mathbf{v}", "context": "Linear algebra"},
    {"name": "Dot Product", "equation": "\\mathbf{a} \\cdot \\mathbf{b} = |\\mathbf{a}||\\mathbf{b}|\\cos\\theta = \\sum_i a_i b_i", "context": "Linear algebra"},
    {"name": "Cross Product", "equation": "\\mathbf{a} \\times \\mathbf{b} = |\\mathbf{a}||\\mathbf{b}|\\sin\\theta \\;\\hat{\\mathbf{n}}", "context": "Vector algebra"},
    {"name": "Scalar Triple Product", "equation": "\\mathbf{a} \\cdot (\\mathbf{b} \\times \\mathbf{c}) = (\\mathbf{a} \\times \\mathbf{b}) \\cdot \\mathbf{c}", "context": "Vector algebra"},
    {"name": "Cauchy-Schwarz Inequality", "equation": "|\\langle \\mathbf{u}, \\mathbf{v} \\rangle|^2 \\leq \\langle \\mathbf{u}, \\mathbf{u} \\rangle \\langle \\mathbf{v}, \\mathbf{v} \\rangle", "context": "Linear algebra"},
    {"name": "Triangle Inequality", "equation": "|\\mathbf{a} + \\mathbf{b}| \\leq |\\mathbf{a}| + |\\mathbf{b}|", "context": "Algebra"},
    {"name": "Arithmetic Series", "equation": "S_n = \\frac{n(a_1 + a_n)}{2}", "context": "Algebra"},
    {"name": "Geometric Series", "equation": "S_n = a\\frac{1 - r^n}{1 - r}", "context": "Algebra"},
    {"name": "Infinite Geometric Series", "equation": "S = \\frac{a}{1-r} \\quad \\text{for } |r|<1", "context": "Algebra"},
    {"name": "Exponential Growth", "equation": "N(t) = N_0 e^{rt}", "context": "Algebra"},
    {"name": "Logistic Growth", "equation": "P(t) = \\frac{K}{1 + \\left(\\frac{K}{P_0} - 1\\right) e^{-rt}}", "context": "Algebra"},
    {"name": "Compound Interest", "equation": "A = P\\left(1 + \\frac{r}{n}\\right)^{nt}", "context": "Financial mathematics"},
    {"name": "Continuous Compounding", "equation": "A = Pe^{rt}", "context": "Financial mathematics"},
    {"name": "Effective Annual Rate", "equation": "\\text{EAR} = \\left(1 + \\frac{r}{n}\\right)^n - 1", "context": "Financial mathematics"},
    {"name": "Present Value", "equation": "\\text{PV} = \\frac{FV}{(1+r)^n}", "context": "Financial mathematics"},
    {"name": "Root Mean Square", "equation": "X_{\\text{rms}} = \\sqrt{\\frac{1}{n}\\sum_i x_i^2}", "context": "Statistics"},
    {"name": "Variance", "equation": "\\operatorname{Var}(X) = \\mathbb{E}[(X-\\mu)^2]", "context": "Statistics"},
    {"name": "Standard Deviation", "equation": "\\sigma = \\sqrt{\\operatorname{Var}(X)}", "context": "Statistics"},
    {"name": "Covariance", "equation": "\\operatorname{Cov}(X,Y) = \\mathbb{E}[(X-\\mu_X)(Y-\\mu_Y)]", "context": "Statistics"},
    # === MATHEMATICS: CALCULUS & ANALYSIS (231-270) ===
    {"name": "Definition of Derivative", "equation": "f'(x) = \\lim_{h \\to 0} \\frac{f(x+h) - f(x)}{h}", "context": "Calculus"},
    {"name": "Power Rule", "equation": "\\frac{d}{dx}(x^n) = nx^{n-1}", "context": "Calculus"},
    {"name": "Product Rule", "equation": "(fg)' = f'g + fg'", "context": "Calculus"},
    {"name": "Quotient Rule", "equation": "\\left(\\frac{f}{g}\\right)' = \\frac{f'g - fg'}{g^2}", "context": "Calculus"},
    {"name": "Chain Rule", "equation": "(f \\circ g)'(x) = f'(g(x)) \\, g'(x)", "context": "Calculus"},
    {"name": "Fundamental Theorem of Calculus I", "equation": "\\int_a^b f(x)\\,dx = F(b) - F(a)", "context": "Calculus"},
    {"name": "Fundamental Theorem of Calculus II", "equation": "\\frac{d}{dx} \\int_a^x f(t)\\,dt = f(x)", "context": "Calculus"},
    {"name": "Integration by Parts", "equation": "\\int u\\,dv = uv - \\int v\\,du", "context": "Calculus"},
    {"name": "L'Hôpital's Rule", "equation": "\\lim_{x \\to c} \\frac{f(x)}{g(x)} = \\lim_{x \\to c} \\frac{f'(x)}{g'(x)}", "context": "Calculus"},
    {"name": "Taylor Series", "equation": "f(x) = \\sum_{n=0}^{\\infty} \\frac{f^{(n)}(a)}{n!} (x-a)^n", "context": "Calculus"},
    {"name": "Maclaurin Series for e^x", "equation": "e^x = \\sum_{n=0}^{\\infty} \\frac{x^n}{n!}", "context": "Calculus"},
    {"name": "Maclaurin Series for sin x", "equation": "\\sin x = \\sum_{n=0}^{\\infty} \\frac{(-1)^n x^{2n+1}}{(2n+1)!}", "context": "Calculus"},
    {"name": "Maclaurin Series for cos x", "equation": "\\cos x = \\sum_{n=0}^{\\infty} \\frac{(-1)^n x^{2n}}{(2n)!}", "context": "Calculus"},
    {"name": "Gradient", "equation": "\\nabla f = \\left(\\frac{\\partial f}{\\partial x}, \\frac{\\partial f}{\\partial y}, \\frac{\\partial f}{\\partial z}\\right)", "context": "Vector calculus"},
    {"name": "Divergence", "equation": "\\nabla \\cdot \\mathbf{F} = \\frac{\\partial F_x}{\\partial x} + \\frac{\\partial F_y}{\\partial y} + \\frac{\\partial F_z}{\\partial z}", "context": "Vector calculus"},
    {"name": "Curl", "equation": "\\nabla \\times \\mathbf{F} = \\left(\\frac{\\partial F_z}{\\partial y} - \\frac{\\partial F_y}{\\partial z},\\; \\frac{\\partial F_x}{\\partial z} - \\frac{\\partial F_z}{\\partial x},\\; \\frac{\\partial F_y}{\\partial x} - \\frac{\\partial F_x}{\\partial y}\\right)", "context": "Vector calculus"},
    {"name": "Laplacian", "equation": "\\nabla^2 f = \\frac{\\partial^2 f}{\\partial x^2} + \\frac{\\partial^2 f}{\\partial y^2} + \\frac{\\partial^2 f}{\\partial z^2}", "context": "Vector calculus"},
    {"name": "Divergence Theorem", "equation": "\\int_V (\\nabla \\cdot \\mathbf{F})\\,dV = \\oint_S \\mathbf{F} \\cdot d\\mathbf{A}", "context": "Vector calculus"},
    {"name": "Stokes' Theorem", "equation": "\\int_S (\\nabla \\times \\mathbf{F}) \\cdot d\\mathbf{A} = \\oint_C \\mathbf{F} \\cdot d\\mathbf{r}", "context": "Vector calculus"},
    {"name": "Green's Theorem", "equation": "\\oint_C (L\\,dx + M\\,dy) = \\iint_D \\left(\\frac{\\partial M}{\\partial x} - \\frac{\\partial L}{\\partial y}\\right) dA", "context": "Vector calculus"},
    {"name": "Mean Value Theorem", "equation": "f'(c) = \\frac{f(b) - f(a)}{b-a}", "context": "Calculus"},
    {"name": "Intermediate Value Theorem", "equation": "f(a) < k < f(b) \\implies \\exists c: f(c) = k", "context": "Calculus"},
    {"name": "Extreme Value Theorem", "equation": "f \\text{ continuous on } [a,b] \\text{ attains max and min}", "context": "Calculus"},
    {"name": "Euler's Formula (Polyhedra)", "equation": "V - E + F = 2", "context": "Topology"},
    {"name": "Gamma Function", "equation": "\\Gamma(n) = \\int_0^{\\infty} t^{n-1} e^{-t}\\,dt", "context": "Special functions"},
    {"name": "Beta Function", "equation": "B(x,y) = \\int_0^1 t^{x-1} (1-t)^{y-1}\\,dt", "context": "Special functions"},
    {"name": "Stirling's Approximation", "equation": "n! \\approx \\sqrt{2\\pi n}\\left(\\frac{n}{e}\\right)^n", "context": "Analysis"},
    {"name": "Riemann Zeta Function", "equation": "\\zeta(s) = \\sum_{n=1}^{\\infty} \\frac{1}{n^s}", "context": "Complex analysis"},
    {"name": "Basel Problem", "equation": "\\sum_{n=1}^{\\infty} \\frac{1}{n^2} = \\frac{\\pi^2}{6}", "context": "Analysis"},
    {"name": "Laplace Transform", "equation": "\\mathcal{L}\\{f(t)\\} = F(s) = \\int_0^{\\infty} f(t) e^{-st}\\,dt", "context": "Calculus"},
    {"name": "Fourier Series", "equation": "f(x) = \\frac{a_0}{2} + \\sum_{n=1}^{\\infty} \\left(a_n \\cos(nx) + b_n \\sin(nx)\\right)", "context": "Analysis"},
    {"name": "Fourier Transform", "equation": "\\hat{f}(\\xi) = \\int_{-\\infty}^{\\infty} f(x) e^{-2\\pi i x \\xi}\\,dx", "context": "Analysis"},
    {"name": "Convolution", "equation": "(f * g)(t) = \\int_{-\\infty}^{\\infty} f(\\tau) g(t-\\tau)\\,d\\tau", "context": "Analysis"},
    {"name": "Cauchy-Riemann Equations", "equation": "\\frac{\\partial u}{\\partial x} = \\frac{\\partial v}{\\partial y}, \\quad \\frac{\\partial u}{\\partial y} = -\\frac{\\partial v}{\\partial x}", "context": "Complex analysis"},
    {"name": "Cauchy Integral Formula", "equation": "f(a) = \\frac{1}{2\\pi i} \\oint_\\gamma \\frac{f(z)}{z-a}\\,dz", "context": "Complex analysis"},
    {"name": "Residue Theorem", "equation": "\\oint_\\gamma f(z)\\,dz = 2\\pi i \\sum_k \\operatorname{Res}(f,a_k)", "context": "Complex analysis"},
    {"name": "Liouville's Theorem", "equation": "\\text{entire bounded } f \\text{ is constant}", "context": "Complex analysis"},
    {"name": "Contour Integration", "equation": "\\int_{-\\infty}^{\\infty} f(x)\\,dx = 2\\pi i \\sum_{\\operatorname{Im}>0} \\operatorname{Res}(f)", "context": "Complex analysis"},
    {"name": "Weierstrass M-Test", "equation": "\\sum M_n \\text{ converges } \\implies \\sum f_n \\text{ converges uniformly}", "context": "Analysis"},
    {"name": "Lagrange Multipliers", "equation": "\\nabla f = \\lambda \\nabla g", "context": "Calculus"},
    # === GEOMETRY & TRIGONOMETRY (271-300) ===
    {"name": "Pythagorean Theorem", "equation": "a^2 + b^2 = c^2", "context": "Geometry"},
    {"name": "Area of a Circle", "equation": "A = \\pi r^2", "context": "Geometry"},
    {"name": "Circumference of a Circle", "equation": "C = 2\\pi r", "context": "Geometry"},
    {"name": "Volume of a Sphere", "equation": "V = \\frac{4}{3}\\pi r^3", "context": "Geometry"},
    {"name": "Surface Area of a Sphere", "equation": "A = 4\\pi r^2", "context": "Geometry"},
    {"name": "Law of Sines", "equation": "\\frac{a}{\\sin A} = \\frac{b}{\\sin B} = \\frac{c}{\\sin C} = 2R", "context": "Trigonometry"},
    {"name": "Law of Cosines", "equation": "c^2 = a^2 + b^2 - 2ab\\cos C", "context": "Trigonometry"},
    {"name": "Sine Addition Formula", "equation": "\\sin(A+B) = \\sin A \\cos B + \\cos A \\sin B", "context": "Trigonometry"},
    {"name": "Cosine Addition Formula", "equation": "\\cos(A+B) = \\cos A \\cos B - \\sin A \\sin B", "context": "Trigonometry"},
    {"name": "Tangent Addition Formula", "equation": "\\tan(A+B) = \\frac{\\tan A + \\tan B}{1 - \\tan A \\tan B}", "context": "Trigonometry"},
    {"name": "Double Angle (Sine)", "equation": "\\sin(2\\theta) = 2\\sin\\theta \\cos\\theta", "context": "Trigonometry"},
    {"name": "Double Angle (Cosine)", "equation": "\\cos(2\\theta) = \\cos^2\\theta - \\sin^2\\theta = 2\\cos^2\\theta-1 = 1-2\\sin^2\\theta", "context": "Trigonometry"},
    {"name": "Pythagorean Identity", "equation": "\\sin^2\\theta + \\cos^2\\theta = 1", "context": "Trigonometry"},
    {"name": "Area of a Triangle (Heron)", "equation": "A = \\sqrt{s(s-a)(s-b)(s-c)}, \\quad s = \\frac{a+b+c}{2}", "context": "Geometry"},
    {"name": "Area of a Triangle (Base-Height)", "equation": "A = \\frac{1}{2}bh", "context": "Geometry"},
    {"name": "Euclidean Distance (2D)", "equation": "d = \\sqrt{(x_2-x_1)^2 + (y_2-y_1)^2}", "context": "Geometry"},
    {"name": "Euclidean Distance (3D)", "equation": "d = \\sqrt{(x_2-x_1)^2 + (y_2-y_1)^2 + (z_2-z_1)^2}", "context": "Geometry"},
    {"name": "Equation of a Circle", "equation": "(x-h)^2 + (y-k)^2 = r^2", "context": "Analytic geometry"},
    {"name": "Equation of an Ellipse", "equation": "\\frac{(x-h)^2}{a^2} + \\frac{(y-k)^2}{b^2} = 1", "context": "Analytic geometry"},
    {"name": "Equation of a Parabola", "equation": "y = a(x-h)^2 + k", "context": "Analytic geometry"},
    {"name": "Equation of a Hyperbola", "equation": "\\frac{(x-h)^2}{a^2} - \\frac{(y-k)^2}{b^2} = 1", "context": "Analytic geometry"},
    {"name": "Slope Formula", "equation": "m = \\frac{y_2 - y_1}{x_2 - x_1}", "context": "Analytic geometry"},
    {"name": "Distance from Point to Line", "equation": "d = \\frac{|Ax_0 + By_0 + C|}{\\sqrt{A^2 + B^2}}", "context": "Analytic geometry"},
    {"name": "Equation of a Line (Point-Slope)", "equation": "y - y_1 = m(x - x_1)", "context": "Analytic geometry"},
    {"name": "Volume of a Cylinder", "equation": "V = \\pi r^2 h", "context": "Geometry"},
    {"name": "Volume of a Cone", "equation": "V = \\frac{1}{3}\\pi r^2 h", "context": "Geometry"},
    {"name": "Volume of a Pyramid", "equation": "V = \\frac{1}{3}Bh", "context": "Geometry"},
    {"name": "Surface Area of a Cylinder", "equation": "\\text{SA} = 2\\pi r^2 + 2\\pi r h", "context": "Geometry"},
    {"name": "Law of Tangents", "equation": "\\frac{a-b}{a+b} = \\frac{\\tan\\frac{1}{2}(A-B)}{\\tan\\frac{1}{2}(A+B)}", "context": "Trigonometry"},
    {"name": "Small Angle Approximations", "equation": "\\sin\\theta \\approx \\theta, \\quad \\cos\\theta \\approx 1-\\frac{\\theta^2}{2}, \\quad \\tan\\theta \\approx \\theta", "context": "Trigonometry"},
    # === NUMBER THEORY (301-320) ===
    {"name": "Euclid's Lemma", "equation": "p \\mid ab \\implies p \\mid a \\text{ or } p \\mid b \\quad (p \\text{ prime})", "context": "Number theory"},
    {"name": "Fundamental Theorem of Arithmetic", "equation": "n = \\prod_i p_i^{a_i} \\quad \\text{(unique factorization)}", "context": "Number theory"},
    {"name": "Fermat's Little Theorem", "equation": "a^p \\equiv a \\pmod{p}", "context": "Number theory"},
    {"name": "Fermat's Last Theorem", "equation": "x^n + y^n = z^n \\text{ has no integer solutions for } n>2", "context": "Number theory"},
    {"name": "Euler's Totient Theorem", "equation": "a^{\\varphi(n)} \\equiv 1 \\pmod{n} \\quad \\text{if } \\gcd(a,n)=1", "context": "Number theory"},
    {"name": "Euler's Totient Function", "equation": "\\varphi(n) = n\\prod_{p|n}\\left(1 - \\frac{1}{p}\\right)", "context": "Number theory"},
    {"name": "Chinese Remainder Theorem", "equation": "x \\equiv a \\pmod{m},\\; x \\equiv b \\pmod{n} \\text{ has unique solution mod } mn", "context": "Number theory"},
    {"name": "Quadratic Formula (mod p)", "equation": "x = \\frac{-b \\pm \\sqrt{b^2-4ac}}{2a} \\pmod{p}", "context": "Number theory"},
    {"name": "Legendre Symbol", "equation": "\\left(\\frac{a}{p}\\right) = a^{(p-1)/2} \\pmod{p}", "context": "Number theory"},
    {"name": "Law of Quadratic Reciprocity", "equation": "\\left(\\frac{p}{q}\\right)\\left(\\frac{q}{p}\\right) = (-1)^{(p-1)(q-1)/4}", "context": "Number theory"},
    {"name": "Prime Number Theorem", "equation": "\\pi(x) \\sim \\frac{x}{\\ln x}", "context": "Number theory"},
    {"name": "Möbius Function", "equation": "\\mu(n) = 0 \\text{ if } n \\text{ has squared prime factor, else } (-1)^k", "context": "Number theory"},
    {"name": "Goldbach's Conjecture", "equation": "\\text{Every even } n>2 \\text{ is sum of 2 primes}", "context": "Number theory"},
    {"name": "Twin Prime Conjecture", "equation": "\\text{There are infinitely many } p \\text{ such that } p+2 \\text{ is prime}", "context": "Number theory"},
    {"name": "Dirichlet's Theorem", "equation": "a, nd+a \\text{ contain infinitely many primes if } \\gcd(a,d)=1", "context": "Number theory"},
    {"name": "Riemann Hypothesis", "equation": "\\text{All non-trivial zeros of } \\zeta(s) \\text{ have } \\operatorname{Re}(s) = \\frac{1}{2}", "context": "Number theory"},
    {"name": "ABC Conjecture", "equation": "\\text{For } \\varepsilon>0,\\; \\operatorname{rad}(abc) < c^{1+\\varepsilon} \\text{ has finitely many coprime solutions}", "context": "Number theory"},
    {"name": "Perfect Number Formula", "equation": "2^{p-1}(2^p - 1) \\text{ is perfect if } 2^p-1 \\text{ is prime}", "context": "Number theory"},
    {"name": "Triangular Number", "equation": "T_n = \\frac{n(n+1)}{2}", "context": "Number theory"},
    {"name": "Sum of Squares (Lagrange)", "equation": "\\text{Every } n \\text{ is sum of at most 4 squares}", "context": "Number theory"},
    # === PROBABILITY & STATISTICS (321-345) ===
    {"name": "Bayes' Theorem", "equation": "P(A|B) = \\frac{P(B|A)P(A)}{P(B)}", "context": "Probability"},
    {"name": "Law of Total Probability", "equation": "P(B) = \\sum_i P(B|A_i)P(A_i)", "context": "Probability"},
    {"name": "Binomial Distribution", "equation": "P(X=k) = \\binom{n}{k} p^k (1-p)^{n-k}", "context": "Probability"},
    {"name": "Poisson Distribution", "equation": "P(X=k) = \\frac{\\lambda^k e^{-\\lambda}}{k!}", "context": "Probability"},
    {"name": "Normal Distribution PDF", "equation": "f(x) = \\frac{1}{\\sigma\\sqrt{2\\pi}} e^{-(x-\\mu)^2/(2\\sigma^2)}", "context": "Statistics"},
    {"name": "Central Limit Theorem", "equation": "\\frac{\\bar{X} - \\mu}{\\sigma/\\sqrt{n}} \\to N(0,1)", "context": "Statistics"},
    {"name": "Law of Large Numbers", "equation": "\\bar{X}_n \\to \\mu \\quad \\text{as } n \\to \\infty", "context": "Probability"},
    {"name": "Chebyshev's Inequality", "equation": "P(|X-\\mu| \\geq k\\sigma) \\leq \\frac{1}{k^2}", "context": "Probability"},
    {"name": "Markov's Inequality", "equation": "P(X \\geq a) \\leq \\frac{\\mathbb{E}[X]}{a}", "context": "Probability"},
    {"name": "Exponential Distribution", "equation": "f(x) = \\lambda e^{-\\lambda x}, \\quad x \\geq 0", "context": "Probability"},
    {"name": "Uniform Distribution", "equation": "f(x) = \\frac{1}{b-a}, \\quad a \\leq x \\leq b", "context": "Probability"},
    {"name": "Chi-Squared Statistic", "equation": "\\chi^2 = \\sum_i \\frac{(O_i - E_i)^2}{E_i}", "context": "Statistics"},
    {"name": "Student's t-Distribution", "equation": "f(t) = \\frac{\\Gamma\\left(\\frac{\\nu+1}{2}\\right)}{\\sqrt{\\nu\\pi}\\,\\Gamma\\left(\\frac{\\nu}{2}\\right)} \\left(1 + \\frac{t^2}{\\nu}\\right)^{-(\\nu+1)/2}", "context": "Statistics"},
    {"name": "F-Distribution", "equation": "f(F) \\propto F^{(d_1/2)-1} \\left(1 + \\frac{d_1F}{d_2}\\right)^{-(d_1+d_2)/2}", "context": "Statistics"},
    {"name": "Pearson Correlation", "equation": "r = \\frac{\\sum_i (x_i - \\bar{x})(y_i - \\bar{y})}{n s_x s_y}", "context": "Statistics"},
    {"name": "Linear Regression", "equation": "\\hat{y} = \\beta_0 + \\beta_1 x", "context": "Statistics"},
    {"name": "R-squared", "equation": "R^2 = 1 - \\frac{\\text{SS}_{\\text{res}}}{\\text{SS}_{\\text{tot}}}", "context": "Statistics"},
    {"name": "Expected Value", "equation": "\\mathbb{E}[X] = \\sum_i x_i P(X=x_i)", "context": "Probability"},
    {"name": "Moment Generating Function", "equation": "M_X(t) = \\mathbb{E}[e^{tX}]", "context": "Probability"},
