    {"name": "Cross-Entropy Loss", "equation": "L = -\\sum_i y_i \\log(\\hat{y}_i)", "context": "Machine learning"},
    {"name": "Kullback-Leibler Divergence", "equation": "D_{\\text{KL}}(P \\| Q) = \\sum_i P(i) \\log\\left(\\frac{P(i)}{Q(i)}\\right)", "context": "Information theory"},
